#!/usr/bin/env bun

// ── Taskboard CLI — dependency-free task manager for Bun ──────────────────────

import { readFileSync, writeFileSync, renameSync, existsSync, realpathSync } from "node:fs";
import { dirname, join } from "node:path";

// ── Types ─────────────────────────────────────────────────────────────────────

interface Task {
  id: number;
  title: string;
  status: "open" | "done";
  createdAt: string;
  completedAt?: string;
  tags?: string[];
  due?: string;
}

interface Database {
  tasks: Task[];
  nextId: number;
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function dbPath(): string {
  const env = process.env.TASKBOARD_FILE;
  if (env !== undefined && env !== "") return env;
  return join(process.cwd(), ".taskboard.json");
}

function loadDB(): Database {
  const path = dbPath();
  if (!existsSync(path)) return { tasks: [], nextId: 1 };
  let raw: string;
  try {
    raw = readFileSync(path, "utf8");
  } catch (e) {
    throw new Error(`cannot read database: ${e instanceof Error ? e.message : String(e)}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error("malformed database: invalid JSON");
  }
  if (typeof parsed !== "object" || parsed === null) throw new Error("malformed database: not an object");
  const obj = parsed as Record<string, unknown>;
  if (!Array.isArray(obj.tasks)) throw new Error("malformed database: missing tasks array");
  if (typeof obj.nextId !== "number" || !Number.isInteger(obj.nextId) || obj.nextId < 1) throw new Error("malformed database: invalid nextId");
  const tasks: Task[] = [];
  for (const t of obj.tasks) {
    if (typeof t !== "object" || t === null) throw new Error("malformed database: invalid task");
    if (typeof t.id !== "number" || !Number.isInteger(t.id)) throw new Error("malformed database: invalid id");
    if (typeof t.title !== "string") throw new Error("malformed database: invalid title");
    if (t.status !== "open" && t.status !== "done") throw new Error("malformed database: invalid status");
    if (typeof t.createdAt !== "string") throw new Error("malformed database: invalid createdAt");
    if (t.completedAt !== undefined && typeof t.completedAt !== "string") throw new Error("malformed database: invalid completedAt");
    if (t.tags !== undefined && !Array.isArray(t.tags)) throw new Error("malformed database: invalid tags");
    if (t.due !== undefined && typeof t.due !== "string") throw new Error("malformed database: invalid due");
    tasks.push(t as Task);
  }
  return { tasks, nextId: obj.nextId as number };
}

function atomicWrite(path: string, data: string): void {
  const dir = dirname(realpathSync(path));
  const tmp = join(dir, `.taskboard-tmp-${process.pid}-${Date.now()}.json`);
  writeFileSync(tmp, data, "utf8");
  renameSync(tmp, path);
}

function saveDB(db: Database): void {
  const path = dbPath();
  const data = JSON.stringify(db, null, 2);
  atomicWrite(path, data);
}

function emit(value: unknown): void {
  process.stdout.write(JSON.stringify(value) + "\n");
}

function fail(message: string): never {
  process.stderr.write(`error: ${message}\n`);
  process.exit(1);
}

function todayLocal(): string {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function isValidDate(s: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const [y, m, d] = s.split("-").map(Number);
  const dt = new Date(y!, m! - 1, d!, 0, 0, 0, 0);
  return dt.getFullYear() === y && dt.getMonth() === m! - 1 && dt.getDate() === d;
}

function normalizeTags(input: string): string[] {
  return Array.from(
    new Set(
      input
        .split(",")
        .map((t) => t.trim())
        .filter((t) => t.length > 0)
        .map((t) => t.toLowerCase())
    )
  );
}

// ── Arg parsing ──────────────────────────────────────────────────────────────

interface ParsedFlags {
  positional: string[];
  flags: Record<string, string | boolean>;
}

function parseArgs(argv: string[]): ParsedFlags {
  const positional: string[] = [];
  const flags: Record<string, string | boolean> = {};
  let i = 0;
  while (i < argv.length) {
    const arg = argv[i]!;
    if (arg === "--") {
      positional.push(...argv.slice(i + 1));
      break;
    }
    if (arg.startsWith("--")) {
      const eqIdx = arg.indexOf("=");
      const name = eqIdx >= 0 ? arg.slice(2, eqIdx) : arg.slice(2);
      if (name.length === 0) throw new Error(`unknown flag: ${arg}`);
      if (eqIdx >= 0) {
        flags[name] = arg.slice(eqIdx + 1);
      } else {
        // Look ahead for a value if the flag expects one, else treat as boolean
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith("--")) {
          flags[name] = next;
          i++;
        } else {
          flags[name] = true;
        }
      }
    } else {
      positional.push(arg);
    }
    i++;
  }
  return { positional, flags };
}

// ── Commands ─────────────────────────────────────────────────────────────────

function cmdAdd(positional: string[], flags: Record<string, string | boolean>): void {
  // title can come from --title flag or positional
  let title: string;
  if (typeof flags.title === "string") {
    title = flags.title;
  } else if (flags.title === true) {
    fail("--title requires a value");
  } else if (positional.length > 0) {
    title = positional.join(" ");
  } else {
    fail("--title is required");
  }

  if (title.trim().length === 0) fail("title must not be empty");

  let tags: string[] | undefined;
  if (flags.tags !== undefined) {
    if (typeof flags.tags !== "string") fail("--tags requires a value");
    tags = normalizeTags(flags.tags);
    if (tags.length === 0) tags = undefined;
  }

  let due: string | undefined;
  if (flags.due !== undefined) {
    if (typeof flags.due !== "string") fail("--due requires a value");
    if (!isValidDate(flags.due)) fail(`impossible date: ${flags.due}`);
    due = flags.due;
  }

  // Check for unknown flags
  const known = new Set(["title", "tags", "due"]);
  for (const k of Object.keys(flags)) if (!known.has(k)) fail(`unknown flag: --${k}`);

  const db = loadDB();
  const task: Task = {
    id: db.nextId,
    title: title.trim(),
    status: "open",
    createdAt: new Date().toISOString(),
  };
  if (tags) task.tags = tags;
  if (due) task.due = due;
  db.tasks.push(task);
  db.nextId++;
  saveDB(db);
  emit(task);
}

function cmdList(positional: string[], flags: Record<string, string | boolean>): void {
  const known = new Set(["status", "tag", "overdue"]);
  for (const k of Object.keys(flags)) if (!known.has(k)) fail(`unknown flag: --${k}`);

  let statusFilter: string | undefined;
  if (flags.status !== undefined) {
    if (typeof flags.status !== "string") fail("--status requires a value");
    if (flags.status !== "open" && flags.status !== "done") fail(`invalid status: ${flags.status}`);
    statusFilter = flags.status;
  }

  let tagFilter: string | undefined;
  if (flags.tag !== undefined) {
    if (typeof flags.tag !== "string") fail("--tag requires a value");
    tagFilter = flags.tag.trim().toLowerCase();
  }

  let overdueDate: string | undefined;
  if (flags.overdue !== undefined) {
    if (typeof flags.overdue !== "string") fail("--overdue requires a value");
    if (!isValidDate(flags.overdue)) fail(`impossible date: ${flags.overdue}`);
    overdueDate = flags.overdue;
  }

  const db = loadDB();
  let tasks = db.tasks.slice().sort((a, b) => a.id - b.id);

  if (statusFilter) tasks = tasks.filter((t) => t.status === statusFilter);
  if (tagFilter) tasks = tasks.filter((t) => (t.tags ?? []).includes(tagFilter));
  if (overdueDate) {
    tasks = tasks.filter((t) => t.status === "open" && t.due !== undefined && t.due < overdueDate!);
  }

  emit(tasks);
}

function cmdDone(positional: string[]): void {
  if (positional.length !== 1) fail("done requires exactly one task ID");
  const id = parseInt(positional[0]!, 10);
  if (!Number.isInteger(id) || id < 1) fail(`invalid id: ${positional[0]}`);

  const db = loadDB();
  const task = db.tasks.find((t) => t.id === id);
  if (!task) fail(`task ${id} not found`);

  if (task.status === "done" && task.completedAt) {
    // Idempotent — return existing task
    emit(task);
    return;
  }

  task.status = "done";
  task.completedAt = new Date().toISOString();
  saveDB(db);
  emit(task);
}

function cmdDelete(positional: string[]): void {
  if (positional.length !== 1) fail("delete requires exactly one task ID");
  const id = parseInt(positional[0]!, 10);
  if (!Number.isInteger(id) || id < 1) fail(`invalid id: ${positional[0]}`);

  const db = loadDB();
  const idx = db.tasks.findIndex((t) => t.id === id);
  if (idx < 0) fail(`task ${id} not found`);

  const [deleted] = db.tasks.splice(idx, 1);
  saveDB(db);
  emit(deleted);
}

function cmdStats(): void {
  const db = loadDB();
  const today = todayLocal();
  const total = db.tasks.length;
  const open = db.tasks.filter((t) => t.status === "open").length;
  const done = db.tasks.filter((t) => t.status === "done").length;
  const overdue = db.tasks.filter(
    (t) => t.status === "open" && t.due !== undefined && t.due < today
  ).length;
  emit({ total, open, done, overdue });
}

// ── Main ──────────────────────────────────────────────────────────────────────

function main(): void {
  const argv = process.argv.slice(2);
  if (argv.length === 0) fail("no command given; expected one of: add, list, done, delete, stats");

  const command = argv[0]!;
  const rest = argv.slice(1);

  if (command === "add") {
    const { positional, flags } = parseArgs(rest);
    cmdAdd(positional, flags);
  } else if (command === "list") {
    const { positional, flags } = parseArgs(rest);
    if (positional.length > 0) fail("list does not accept positional arguments");
    cmdList(positional, flags);
  } else if (command === "done") {
    const { positional, flags } = parseArgs(rest);
    if (Object.keys(flags).length > 0) fail("done does not accept flags");
    cmdDone(positional);
  } else if (command === "delete") {
    const { positional, flags } = parseArgs(rest);
    if (Object.keys(flags).length > 0) fail("delete does not accept flags");
    cmdDelete(positional);
  } else if (command === "stats") {
    if (rest.length > 0) fail("stats does not accept arguments");
    cmdStats();
  } else {
    fail(`unknown command: ${command}`);
  }
}

try {
  main();
} catch (e) {
  fail(e instanceof Error ? e.message : String(e));
}

