display.text:
import { existsSync, readFileSync, writeFileSync, unlinkSync, renameSync } from "fs";
import { join, dirname, basename } from "path";

interface Task {
  id: number;
  title: string;
  status: "open" | "done";
  tags: string[];
  due: string | null;
  createdAt: string;
  completedAt: string | null;
}

interface Database {
  tasks: Task[];
  nextId: number;
}

function getDbPath(): string {
  return process.env.TASKBOARD_FILE ?? ".taskboard.json";
}

function die(msg: string): never {
  console.error(msg);
  process.exit(1);
}

function loadDb(): Database {
  const path = getDbPath();
  if (!existsSync(path)) {
    return { tasks: [], nextId: 1 };
  }
  let raw: string;
  try {
    raw = readFileSync(path, "utf-8");
  } catch (e) {
    die(`error: cannot read database file: ${e}`);
  }
  let data: unknown;
  try {
    data = JSON.parse(raw as string);
  } catch {
    die("error: malformed database — not valid JSON");
  }
  if (typeof data !== "object" || data === null || Array.isArray(data)) {
    die("error: malformed database — expected an object");
  }
  const obj = data as Record<string, unknown>;
  if (!Array.isArray(obj.tasks) || typeof obj.nextId !== "number") {
    die("error: malformed database — missing tasks or nextId");
  }
  // Validate each task has required fields
  for (const t of obj.tasks) {
    if (
      typeof t !== "object" || t === null ||
      typeof (t as Task).id !== "number" ||
      typeof (t as Task).title !== "string" ||
      ((t as Task).status !== "open" && (t as Task).status !== "done") ||
      !Array.isArray((t as Task).tags) ||
      (typeof (t as Task).due !== "string" && (t as Task).due !== null) ||
      typeof (t as Task).createdAt !== "string" ||
      (typeof (t as Task).completedAt !== "string" && (t as Task).completedAt !== null)
    ) {
      die("error: malformed database — invalid task entry");
    }
  }
  return { tasks: obj.tasks as Task[], nextId: obj.nextId as number };
}

function saveDb(db: Database): void {
  const path = getDbPath();
  const dir = dirname(path);
  const base = basename(path);
  const tmpPath = join(dir, `.${base}.tmp.${process.pid}`);
  try {
    writeFileSync(tmpPath, JSON.stringify(db, null, 2), "utf-8");
  } catch (e) {
    die(`error: failed to write temp file: ${e}`);
  }
  try {
    renameSync(tmpPath, path);
  } catch (e) {
    try { unlinkSync(tmpPath); } catch {}
    die(`error: failed to save database: ${e}`);
  }
}

function out(value: unknown): void {
  console.log(JSON.stringify(value));
}

function parseDate(s: string): string {
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) die(`error: invalid date format "${s}" — expected YYYY-MM-DD`);
  const year = parseInt(m[1], 10);
  const month = parseInt(m[2], 10);
  const day = parseInt(m[3], 10);
  const d = new Date(year, month - 1, day);
  if (
    d.getFullYear() !== year ||
    d.getMonth() !== month - 1 ||
    d.getDate() !== day
  ) {
    die(`error: impossible date "${s}"`);
  }
  return s;
}

function normalizeTags(raw: string | undefined): string[] {
  if (raw === undefined) return [];
  const tags = raw.split(",").map((t) => t.trim()).filter((t) => t.length > 0);
  // lowercase and deduplicate
  const seen = new Set<string>();
  const result: string[] = [];
  for (const t of tags) {
    const lower = t.toLowerCase();
    if (!seen.has(lower)) {
      seen.add(lower);
      result.push(lower);
    }
  }
  return result;
}

function todayLocal(): string {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, "0");
  const d = String(now.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function isoNow(): string {
  return new Date().toISOString();
}

function findTask(db: Database, id: number): Task {
  const task = db.tasks.find((t) => t.id === id);
  if (!task) die(`error: task ${id} not found`);
  return task;
}

function parseArgs(args: string[]): { command: string; positional: number[]; flags: Record<string, string | boolean> } {
  const result: { command: string; positional: number[]; flags: Record<string, string | boolean> } = {
    command: "",
    positional: [],
    flags: {},
  };
  if (args.length === 0) die("error: no command given");
  result.command = args[0];
  let i = 1;
  // Flags that accept a value
  const valueFlags = new Set(["--title", "--tags", "--due", "--status", "--tag", "--overdue"]);
  while (i < args.length) {
    const arg = args[i];
    if (arg.startsWith("--")) {
      const name = arg;
      if (valueFlags.has(name)) {
        if (i + 1 >= args.length) die(`error: flag ${name} requires a value`);
        result.flags[name] = args[i + 1];
        i += 2;
      } else {
        die(`error: unknown flag ${name}`);
      }
    } else {
      const num = parseInt(arg, 10);
      if (isNaN(num)) die(`error: unexpected argument "${arg}"`);
      result.positional.push(num);
      i += 1;
    }
  }
  return result;
}

function cmdAdd(db: Database, flags: Record<string, string | boolean>): void {
  const title = flags["--title"];
  if (typeof title !== "string" || title.trim().length === 0) {
    die("error: --title TEXT is required and must be non-empty");
  }
  const dueRaw = flags["--due"];
  let due: string | null = null;
  if (typeof dueRaw === "string") {
    due = parseDate(dueRaw);
  }
  const tags = normalizeTags(typeof flags["--tags"] === "string" ? flags["--tags"] as string : undefined);
  const task: Task = {
    id: db.nextId,
    title: title,
    status: "open",
    tags,
    due,
    createdAt: isoNow(),
    completedAt: null,
  };
  db.tasks.push(task);
  db.nextId += 1;
  saveDb(db);
  out(task);
}

function cmdList(db: Database, flags: Record<string, string | boolean>): void {
  let tasks = [...db.tasks];
  const statusFilter = flags["--status"];
  if (typeof statusFilter === "string") {
    if (statusFilter !== "open" && statusFilter !== "done") {
      die(`error: invalid --status value "${statusFilter}" — expected open|done`);
    }
    tasks = tasks.filter((t) => t.status === statusFilter);
  }
  const tagFilter = flags["--tag"];
  if (typeof tagFilter === "string") {
    const norm = tagFilter.trim().toLowerCase();
    if (norm.length === 0) die("error: --tag must not be empty");
    tasks = tasks.filter((t) => t.tags.includes(norm));
  }
  const overdueFilter = flags["--overdue"];
  if (typeof overdueFilter === "string") {
    const refDate = parseDate(overdueFilter);
    tasks = tasks.filter(
      (t) => t.status === "open" && t.due !== null && t.due < refDate
    );
  }
  tasks.sort((a, b) => a.id - b.id);
  out(tasks);
}

function cmdDone(db: Database, positional: number[]): void {
  if (positional.length < 1) die("error: done requires a task ID");
  const task = findTask(db, positional[0]);
  if (task.status === "done") {
    out(task);
    return;
  }
  task.status = "done";
  task.completedAt = isoNow();
  saveDb(db);
  out(task);
}

function cmdDelete(db: Database, positional: number[]): void {
  if (positional.length < 1) die("error: delete requires a task ID");
  const id = positional[0];
  const idx = db.tasks.findIndex((t) => t.id === id);
  if (idx === -1) die(`error: task ${id} not found`);
  const [deleted] = db.tasks.splice(idx, 1);
  saveDb(db);
  out({ id: deleted.id, deleted: true });
}

function cmdStats(db: Database): void {
  const today = todayLocal();
  const total = db.tasks.length;
  const open = db.tasks.filter((t) => t.status === "open").length;
  const done = db.tasks.filter((t) => t.status === "done").length;
  const overdue = db.tasks.filter(
    (t) => t.status === "open" && t.due !== null && t.due < today
  ).length;
  out({ total, open, done, overdue });
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length === 0) die("error: no command given");
  const command = args[0];
  const rest = args.slice(1);
  const parsed = parseArgs([command, ...rest]);
  parsed.command = command;

  const db = loadDb();
  switch (command) {
    case "add":
      cmdAdd(db, parsed.flags);
      break;
    case "list":
      cmdList(db, parsed.flags);
      break;
    case "done":
      cmdDone(db, parsed.positional);
      break;
    case "delete":
      cmdDelete(db, parsed.positional);
      break;
    case "stats":
      cmdStats(db);
      break;
    default:
      die(`error: unknown command "${command}"`);
  }
}

main();

