  } catch (e) {
    die(`error: cannot read database file: ${e}`);
  }
  let data: unknown;
  try {
    data = JSON.parse(raw as string);
  } catch {
    die("error: malformed database — not valid JSON");
  }
  if (typeof data !== "object" || data === null || Array.isArray(data)) {
    die("error: malformed database — expected an object");
  }
  const obj = data as Record<string, unknown>;
  if (!Array.isArray(obj.tasks) || typeof obj.nextId !== "number") {
    die("error: malformed database — missing tasks or nextId");
  }
  // Validate each task has required fields
  for (const t of obj.tasks) {
    if (
      typeof t !== "object" || t === null ||
      typeof (t as Task).id !== "number" ||
      typeof (t as Task).title !== "string" ||
      ((t as Task).status !== "open" && (t as Task).status !== "done") ||
      !Array.isArray((t as Task).tags) ||
      (typeof (t as Task).due !== "string" && (t as Task).due !== null) ||
      typeof (t as Task).createdAt !== "string" ||
      (typeof (t as Task).completedAt !== "string" && (t as Task).completedAt !== null)
    ) {
      die("error: malformed database — invalid task entry");
    }
  }
  return { tasks: obj.tasks as Task[], nextId: obj.nextId as number };
}

function saveDb(db: Database): void {
  const path = getDbPath();
  const dir = dirname(path);
  const base = basename(path);
  const tmpPath = join(dir, `.${base}.tmp.${process.pid}`);
  try {
    writeFileSync(tmpPath, JSON.stringify(db, null, 2), "utf-8");
  } catch (e) {
    die(`error: failed to write temp file: ${e}`);
  }
  try {
    renameSync(tmpPath, path);
  } catch (e) {
